 elif m in grocery: c='Groceries'
 elif m in transport: c='Transport: fuel/auto'
 elif m in travel: c='Transport: parking/travel'
 elif m in health: c='Health / fitness'
 elif m in subs: c='Subscriptions / utilities'
 elif m in ['AMC Theatres','Steam','Spotify Concert','Ticketmaster']: c='Entertainment'
 else: c='Uncategorized'
 r.append(c)
monthly=defaultdict(lambda:defaultdict(int))
for r in clean: monthly[(r[1].year,r[1].month)][r[5]]+=round(r[3]*100)
print('UNPARSED',bad); print('DUPLICATE_DROPPED',[(r[0],r[1],r[2],r[3]) for r in duplicates]); print('UNCATEGORIZED',[(r[0],r[1],r[2],r[3]) for r in clean if r[5]=='Uncategorized']); print('REFUND',[(r[0],r[1],r[2],r[3],r[5]) for r in clean if r[3]<0])
print('MONTHLY')
for ym in sorted(monthly): print(ym,{k:round(v/100,2) for k,v in sorted(monthly[ym].items())})
print('BUDGET')
for ym in sorted(monthly):
 for c,t in [('Eating out / coffee',26000),('Amazon/shopping',120000)]: print(ym,c,round(monthly[ym][c]/100,2),round((monthly[ym][c]-t)/100,2))
print('CHANGES')
ys=sorted(monthly); cats=sorted({x for m in monthly.values() for x in m})
for a,b in zip(ys,ys[1:]): print(a,b,[(c,round((monthly[b][c]-monthly[a][c])/100,2)) for c in cats if monthly[b][c]"'!=monthly[a][c]])
